style.css:
@-moz-document domain("oyc.yale.edu") {
/* Main */
html,
body{
    background:#0d1117 !important;
    color:#e6edf3 !important;
}

/* Everything */
body *{
    border-color:#30363d !important;
}

/* Content */
main,
article,
section,
.content,
.region,
.container,
.wrapper,
.page,
#main,
#content{
    background:#0d1117 !important;
    color:#e6edf3 !important;
}

/* Text */
p,
li,
span,
td,
th{
    color:#d0d7de !important;
}

h1,h2,h3,h4,h5,h6{
    color:#ffffff !important;
}

/* Links */
a{
    color:#58a6ff !important;
}

a:hover{
    color:#79c0ff !important;
}

/* Navigation */
header,
footer,
nav,
aside{
    background:#161b22 !important;
}

/* Cards */
.card,
.panel,
.views-row,
.block{
    background:#161b22 !important;
    border:1px solid #30363d !important;
}

/* Code */
pre,
code{
    background:#161b22 !important;
    color:#7ee787 !important;
}

/* Tables */
table{
    background:#161b22 !important;
}

th{
    background:#21262d !important;
}

/* Inputs */
input,
textarea,
select{
    background:#161b22 !important;
    color:#fff !important;
}

/* Embedded transcript */
iframe{
    filter:invert(0.93) hue-rotate(180deg);
}

/* Images stay normal */
img,
video,
svg{
    filter:none !important;
}

/* Scrollbar */
::-webkit-scrollbar{
    width:10px;
}

::-webkit-scrollbar-thumb{
    background:#444;
}

::-webkit-scrollbar-track{
    background:#111;
}
}
